def esc(s): return s.replace("&", "&amp;").replace("'", "\\'").replace('"', '\\"').replace("\n", "\\n")
for loc, vals in T.items():
    assert len(vals) == len(KEYS), (loc, len(vals))
    p = f"app/src/main/res/values-{loc}/strings.xml"
    s = open(p, encoding="utf-8").read()
    s = re.sub(r"\n    <!-- step35 -->.*?<!-- /step35 -->", "", s, flags=re.S)
    d = dict(zip(KEYS, vals))
    body = "".join(f'    <string name="{k}">{esc(d[k])}</string>\n' for k in KEYS if not k.startswith("@"))
    body += ('    <plurals name="pages_and_size">\n'
             f'        <item quantity="one">{esc(d["@one"])}</item>\n'
             f'        <item quantity="other">{esc(d["@other"])}</item>\n'
             '    </plurals>\n')
    s = s.replace("\n</resources>", "\n    <!-- step35 -->\n" + body + "    <!-- /step35 -->\n</resources>")
    open(p, "w", encoding="utf-8").write(s)
print("step35 translations:", len(T))
